//! A registered player.

use sea_orm::entity::prelude::*;

/// One account. The username is the login; the display name is what other
/// players see.
#[derive(Clone, Debug, PartialEq, Eq, DeriveEntityModel)]
#[sea_orm(table_name = "account")]
pub struct Model {
    /// `UUIDv7`, generated by the gateway. See the crate doc on why the key
    /// is time-ordered.
    #[sea_orm(primary_key, auto_increment = false)]
    pub id: Uuid,
    /// The e-mail address, stored as the player typed it; `None` for an
    /// account made without one, which since usernames (#269) is every new
    /// one.
    ///
    /// Uniqueness is enforced on `lower(email)` by an expression index
    /// rather than by lowercasing the column, because the address a
    /// confirmation mail is sent to should be the one its owner recognises.
    pub email: Option<String>,
    /// The login name as its owner typed it, after the rule's folding
    /// (`baylee_protocol::names`). Private: never shown to another player.
    /// `None` only for an account that does not sign in with one.
    pub username: Option<String>,
    /// What [`Self::username`] is unique under and looked up by: its lower
    /// case.
    pub username_key: Option<String>,
    /// Display name. **Not** unique: two players may both be Alice.
    pub display_name: String,
    /// The discriminator that tells two Alices apart, rendered to a player
    /// as lowercase hex — `Alice#af03`.
    ///
    /// An identity column, so the database hands it out and the gateway
    /// never picks one. It is therefore also a registration counter, which
    /// is a leak the design accepts: the same one a `BattleTag` has, and the
    /// price of a tag you can type at somebody rather than a second UUID.
    pub tag: i32,
    /// Argon2id PHC hash. Never a password. `None` for a guest, and only
    /// for one.
    pub password_hash: Option<String>,
    /// When the account was created.
    pub created_at: TimeDateTimeWithTimeZone,
    /// When the address was confirmed, if it ever was.
    ///
    /// `None` means two different things and the mailer decides which: on a
    /// gateway that sends mail it means the account cannot sign in yet; on
    /// one with no SMTP configured it means nothing at all, because nobody
    /// was ever asked. That is why it is a nullable timestamp and not a
    /// boolean — "never asked" and "asked and unanswered" are the same
    /// state, and only the configuration tells them apart.
    pub confirmed_at: Option<TimeDateTimeWithTimeZone>,
    /// The language the account registered in, for the mail it is sent.
    pub lang: String,
    /// Handed out by `POST /auth/guest` (#269): no username, no address, no
    /// password, and gone once its last session is. The database holds a
    /// guest to exactly that.
    pub guest: bool,
}

/// Everything that belongs to an account and dies with it.
#[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
pub enum Relation {
    /// The player's decks.
    #[sea_orm(has_many = "super::deck::Entity")]
    Deck,
    /// Live sessions.
    #[sea_orm(has_many = "super::session_token::Entity")]
    SessionToken,
    /// Unspent confirmation links.
    #[sea_orm(has_many = "super::confirmation::Entity")]
    Confirmation,
    /// The one preferences document.
    #[sea_orm(has_one = "super::client_settings::Entity")]
    ClientSettings,
    /// Its claim on uploaded pictures (#292).
    #[sea_orm(has_many = "super::upload::Entity")]
    Upload,
}

impl Related<super::deck::Entity> for Entity {
    fn to() -> RelationDef {
        Relation::Deck.def()
    }
}

impl Related<super::session_token::Entity> for Entity {
    fn to() -> RelationDef {
        Relation::SessionToken.def()
    }
}

impl Related<super::confirmation::Entity> for Entity {
    fn to() -> RelationDef {
        Relation::Confirmation.def()
    }
}

impl Related<super::client_settings::Entity> for Entity {
    fn to() -> RelationDef {
        Relation::ClientSettings.def()
    }
}

impl Related<super::upload::Entity> for Entity {
    fn to() -> RelationDef {
        Relation::Upload.def()
    }
}

impl ActiveModelBehavior for ActiveModel {}
